--- 获取排名奖励数据
---@return CompeteRankRewardsVo[]
function CompeteComponent:GetCompeteRankRewards()
    --- 获取对应的排期
    local scheduleId = self.Dojo:GetScheduleId()
    ---@type CompeteRankRewardsVo[]
    local competeRankRewardsVos = CfUtils.GetCf(AutoIds.IdSetting2771, "CompeteRankRewardsVo", true)
    ---@type CompeteRankRewardsVo[]
    local competeRankRewards = {}
    local peopleId = self.Dojo:GetPlayerPeopleId()
    -- 筛选符合标准的排名奖励
    for _, v in pairs(competeRankRewardsVos) do
        if v.people == peopleId and scheduleId == v.activityId then
            competeRankRewards[#competeRankRewards + 1] = v
        end
    end
    -- 生序排列
    table.sort(competeRankRewards, function(a, b)
        return a.lowerLimit < b.lowerLimit
    end)
    return competeRankRewards
end
---判断是否是首次进入
function CompeteComponent:GetCurrentDayIsFirstEnter()
    local day = checkInt(CfUtils.GetLocalData(string.format("Compete_Enter_Time_%s",self:GetActivityUuid()), "0"))
    if day == 0 then
        return true
    end
    local currentDay = checkInt(os.date("%Y%m%d"))
    if currentDay > day then
        return true
    end
    return false
end

