function CompeteComponent:GetSelectPlayerPeopleIndex()
    local activityConf = self:GetActivityConf()
    local people = activityConf.people
    local peopleId = self:GetPlayerPeopleId()
    local index = 1
    for i, v in pairs(people) do
        if checkInt(v) == peopleId then
            index = i
            break
        end
    end
    return  index
end

function CompeteComponent:GetEndStoryId()
    local activityConf = self:GetActivityConf()
    local userPkPointInfo = self:GetUserPkPointInfo()
    local people = activityConf.people
    local index = checkInt(userPkPointInfo[tostring(people[1])]) >= checkInt(userPkPointInfo[tostring(people[2])]) and 1 or 2
    local endStoryId = activityConf.endStoryId[index]
    return checkInt(endStoryId)
end
--- 获取结束剧情是否播放
---@return boolean 所否播放
function CompeteComponent:IsPlayEndStoryId()
    local isPlay = CfUtils.GetLocalData(string.format("Compete_End_StoryId_%s_%s", self:GetActivityUuid(),self:GetEndStoryId()), "0")
    if checkInt(isPlay) == 0 then
        return false
    end
    return true
end

