----@return integer   0 、不可以领取 1 、可以领取 ， 2 、已领取
function CompeteComponent:GetGrandPointStatusById(id)
    local currentPoint = self.Dojo:GetCurrentPoint()
    local currentRewardsConf = self.Dojo:GetGrandPoint(id)
    if currentRewardsConf.status == Constants.GetStatus.Has then
        return Constants.GetStatus.Has
    end
    if currentPoint >= checkInt(currentRewardsConf.needPoint) then
        return Constants.GetStatus.Can
    end
    return Constants.GetStatus.Not
end

