--- 返回排序的积分奖励 已领取在后面， 未领取在前面
function CompeteComponent:GetSortGrandPoint()
    local pointRewardsConf = self.Dojo:GetPointRewards()
    local hasArray = {}
    local noHasArray = {}
    for i, v in pairs(pointRewardsConf) do
        if v.status == Constants.GetStatus.Has then
            hasArray[#hasArray+1] = v
        else
            noHasArray[#noHasArray+1] = v
        end
    end
    if #noHasArray > 0 then
        table.sort(noHasArray, function(a, b)
            if a.status == b.status then
                return a.needPoint < b.needPoint
            end
            return a.status > b.status
        end)
    end
    table.move(hasArray , 1, #hasArray, #noHasArray+1 ,noHasArray)
    return noHasArray
end
